"""
Pydantic schemas for the Agents service.

"""

import time
import uuid
from enum import Enum
from typing import Any, Optional

from pydantic import BaseModel, ConfigDict, Field


class AgentTool(str, Enum):
    """Supported AI coding tool identifiers."""

    CLAUDE = "claude"
    CODEQ = "codeq"
    CODEX = "codex"


class AgentStatus(str, Enum):
    """Agent session status."""

    WORKING = "working"
    WAITING = "waiting"
    IDLE = "idle"
    ERROR = "error"
    STOPPED = "stopped"


class AgentType(str, Enum):
    """Agent type with associated permission profile."""

    LEADER = "leader"
    WORKER = "worker"
    OBSERVER = "observer"
    REVIEWER = "reviewer"


class MessageType(str, Enum):
    """Inter-agent message types."""

    MESSAGE = "message"
    TASK_ASSIGNMENT = "task_assignment"
    STATUS_UPDATE = "status_update"
    SHUTDOWN_REQUEST = "shutdown_request"


class GitInfo(BaseModel):
    """Git repository metadata for a session's working directory."""

    model_config = ConfigDict(populate_by_name=True, extra="ignore", protected_namespaces=())

    branch: Optional[str] = Field(default=None, alias="gitBranch")
    remote_url: Optional[str] = Field(default=None, alias="githubRepo")
    is_worktree: bool = Field(default=False, alias="gitWorktree")


class MCPServerInfo(BaseModel):
    """MCP server connection info."""

    model_config = ConfigDict(populate_by_name=True, extra="ignore", protected_namespaces=())

    name: str = ""


class AgentTask(BaseModel):
    """A task tracked by an agent (e.g. Claude task list)."""

    model_config = ConfigDict(populate_by_name=True, extra="ignore", protected_namespaces=())

    id: str = ""
    subject: str = ""
    status: str = Field(default="pending")
    active_form: str = Field(default="", alias="activeForm")


class TranscriptEntry(BaseModel):
    """A single parsed transcript event."""

    model_config = ConfigDict(populate_by_name=True, extra="ignore", protected_namespaces=())

    id: str = ""
    type: str = ""
    timestamp: Optional[float] = None
    content: str = ""
    model: Optional[str] = None
    tool_name: Optional[str] = Field(default=None, alias="toolName")
    tool_id: Optional[str] = Field(default=None, alias="toolId")
    tool_success: Optional[bool] = Field(default=None, alias="toolSuccess")
    cost_usd: Optional[float] = Field(default=None, alias="costUSD")
    token_count: Optional[int] = Field(default=None, alias="tokenCount")


class AgentMessage(BaseModel):
    """A single inter-agent message."""

    model_config = ConfigDict(populate_by_name=True, extra="ignore", protected_namespaces=())

    id: str = Field(default_factory=lambda: str(uuid.uuid4())[:8])
    from_session: str = Field(default="", alias="fromSession")
    to_session: str = Field(default="", alias="toSession")
    text: str = ""
    timestamp: float = Field(default_factory=time.time)
    type: MessageType = Field(default=MessageType.MESSAGE)
    read: bool = False


class AgentSession(BaseModel):
    """Full agent session model.

    Includes future-phase fields (messaging, teams) with safe defaults
    so the schema never needs a breaking migration.
    """

    model_config = ConfigDict(populate_by_name=True, extra="ignore", protected_namespaces=())

    # Identity
    session_id: str = Field(default="", alias="sessionId")
    tool: AgentTool = Field(default=AgentTool.CLAUDE)
    pid: int = 0
    machine_id: Optional[str] = Field(default=None, alias="machineId")

    # Runtime state
    status: AgentStatus = Field(default=AgentStatus.IDLE)
    cwd: Optional[str] = None
    port: Optional[int] = None
    terminal_name: Optional[str] = Field(default=None, alias="terminalName")
    external: bool = False

    # Launcher tracking
    tmux_session: Optional[str] = Field(default=None, alias="tmuxSession")
    tmux_window: Optional[str] = Field(default=None, alias="tmuxWindow")

    # Compute tracking
    compute_id: Optional[str] = Field(default=None, alias="computeId")
    cluster_id: Optional[str] = Field(default=None, alias="clusterId")

    # Rich details
    model_name: Optional[str] = Field(default=None, alias="model")
    git: Optional[GitInfo] = None
    mcp_servers: list[str] = Field(default_factory=list, alias="mcpServers")
    transcript_path: Optional[str] = Field(default=None, alias="transcriptPath")
    cost_usd: Optional[float] = Field(default=None, alias="costUsd")
    total_tokens: Optional[int] = Field(default=None, alias="totalTokens")
    tasks: list[AgentTask] = Field(default_factory=list)

    # Timestamps
    started_at: Optional[float] = Field(default=None, alias="startedAt")
    last_activity: Optional[float] = Field(default=None, alias="lastActivity")

    # Phase 3 extension: messaging
    message_inbox: list[dict[str, Any]] = Field(default_factory=list, alias="messageInbox")

    # Phase 4 extension: teams
    team_id: Optional[str] = Field(default=None, alias="teamId")
    parent_session_id: Optional[str] = Field(default=None, alias="parentSessionId")
    child_session_ids: list[str] = Field(default_factory=list, alias="childSessionIds")
    role: Optional[str] = None

    # Agent type (permission-aware, alongside legacy role field)
    agent_type: Optional[str] = Field(default=None, alias="agentType")

    # General extension
    tags: list[str] = Field(default_factory=list)
    metadata: dict[str, Any] = Field(default_factory=dict)


class AgentSessionSummary(BaseModel):
    """Lightweight session projection for list views.

    Omits transcript, mcp_servers, tasks, and message_inbox.
    """

    model_config = ConfigDict(populate_by_name=True, extra="ignore", protected_namespaces=())

    session_id: str = Field(default="", alias="sessionId")
    tool: AgentTool = Field(default=AgentTool.CLAUDE)
    pid: int = 0
    status: AgentStatus = Field(default=AgentStatus.IDLE)
    cwd: Optional[str] = None
    terminal_name: Optional[str] = Field(default=None, alias="terminalName")
    external: bool = False
    model_name: Optional[str] = Field(default=None, alias="model")
    git: Optional[GitInfo] = None
    cost_usd: Optional[float] = Field(default=None, alias="costUsd")
    total_tokens: Optional[int] = Field(default=None, alias="totalTokens")
    started_at: Optional[float] = Field(default=None, alias="startedAt")
    last_activity: Optional[float] = Field(default=None, alias="lastActivity")
    team_id: Optional[str] = Field(default=None, alias="teamId")
    role: Optional[str] = None
    agent_type: Optional[str] = Field(default=None, alias="agentType")
    compute_id: Optional[str] = Field(default=None, alias="computeId")
    tmux_session: Optional[str] = Field(default=None, alias="tmuxSession")
    tags: list[str] = Field(default_factory=list)


class SessionRegistry(BaseModel):
    """Root model for the sessions.json file."""

    model_config = ConfigDict(populate_by_name=True, extra="ignore", protected_namespaces=())

    sessions: list[AgentSession] = Field(default_factory=list)
    version: int = 1
